import { Skeleton } from '@/components/ui/skeleton'
import { PageShell } from '@/components/shared/PageShell'

type SkeletonVariant =
  | 'dashboard'
  | 'list'
  | 'grid'
  | 'tabs'
  | 'two-pane'
  | 'calendar'
  | 'hub'
  | 'chart'
  | 'generic'

interface PageSkeletonProps {
  variant: SkeletonVariant
  fullHeight?: boolean
}

function DashboardSkeleton() {
  return (
    <PageShell>
      <Skeleton className="h-8 w-48 mb-2" />
      <Skeleton className="h-4 w-64 mb-8" />
      {/* KPI cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
        {[1, 2, 3, 4].map((i) => (
          <Skeleton key={i} className="h-24 rounded-xl" />
        ))}
      </div>
      {/* Quick actions row */}
      <div className="flex gap-3 mb-8">
        {[1, 2, 3, 4].map((i) => (
          <Skeleton key={i} className="h-9 w-28 rounded-lg" />
        ))}
      </div>
      {/* Queue heading + horizontal scroll cards */}
      <Skeleton className="h-6 w-36 mb-3" />
      <div className="flex gap-3 overflow-hidden mb-8">
        {[1, 2, 3, 4].map((i) => (
          <Skeleton key={i} className="h-28 w-[260px] rounded-xl shrink-0" />
        ))}
      </div>
      {/* Agenda heading + rows */}
      <Skeleton className="h-6 w-32 mb-3" />
      <div className="space-y-2">
        {[1, 2, 3, 4, 5].map((i) => (
          <Skeleton key={i} className="h-14 w-full rounded-lg" />
        ))}
      </div>
    </PageShell>
  )
}

function ListSkeleton() {
  return (
    <PageShell>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <Skeleton className="h-8 w-40 mb-1.5" />
          <Skeleton className="h-4 w-56" />
        </div>
        <Skeleton className="h-9 w-32 rounded-lg" />
      </div>
      {/* Filter bar */}
      <div className="flex gap-2 mb-4">
        <Skeleton className="h-9 w-64 rounded-lg" />
        <Skeleton className="h-9 w-28 rounded-lg" />
        <Skeleton className="h-9 w-24 rounded-lg" />
      </div>
      {/* Table header */}
      <Skeleton className="h-10 w-full rounded-lg mb-1" />
      {/* Table rows */}
      <div className="space-y-1">
        {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
          <Skeleton key={i} className="h-14 w-full rounded-lg" />
        ))}
      </div>
      {/* Pagination */}
      <div className="flex items-center justify-between mt-4">
        <Skeleton className="h-4 w-32" />
        <div className="flex gap-1">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-8 w-8 rounded-md" />
          ))}
        </div>
      </div>
    </PageShell>
  )
}

function GridSkeleton() {
  return (
    <PageShell>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <Skeleton className="h-8 w-40 mb-1.5" />
          <Skeleton className="h-4 w-56" />
        </div>
        <Skeleton className="h-9 w-32 rounded-lg" />
      </div>
      {/* Filter row */}
      <div className="flex gap-2 mb-6">
        <Skeleton className="h-9 w-56 rounded-lg" />
        <Skeleton className="h-9 w-24 rounded-lg" />
      </div>
      {/* Card grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
          <Skeleton key={i} className="h-48 rounded-xl" />
        ))}
      </div>
    </PageShell>
  )
}

function TabsSkeleton() {
  return (
    <PageShell>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <Skeleton className="h-8 w-44 mb-1.5" />
          <Skeleton className="h-4 w-60" />
        </div>
        <Skeleton className="h-9 w-32 rounded-lg" />
      </div>
      {/* Tab row */}
      <div className="flex gap-1 border-b border-border/50 mb-6">
        {[1, 2, 3, 4].map((i) => (
          <Skeleton key={i} className="h-9 w-24 rounded-t-md" />
        ))}
      </div>
      {/* Filter row inside tab */}
      <div className="flex gap-2 mb-4">
        <Skeleton className="h-9 w-56 rounded-lg" />
        <Skeleton className="h-9 w-24 rounded-lg" />
        <Skeleton className="h-9 w-24 rounded-lg" />
      </div>
      {/* Table header */}
      <Skeleton className="h-10 w-full rounded-lg mb-1" />
      {/* Table rows */}
      <div className="space-y-1">
        {[1, 2, 3, 4, 5, 6, 7].map((i) => (
          <Skeleton key={i} className="h-14 w-full rounded-lg" />
        ))}
      </div>
    </PageShell>
  )
}

function TwoPaneSkeleton() {
  return (
    <PageShell fullHeight>
      <div className="flex min-h-0 flex-1">
        {/* Thread list panel */}
        <div className="flex w-80 shrink-0 flex-col border-r border-border/50 px-3 py-4 gap-2">
          <Skeleton className="h-9 w-full rounded-lg mb-2" />
          {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <Skeleton key={i} className="h-16 w-full rounded-lg" />
          ))}
        </div>
        {/* Thread panel */}
        <div className="flex flex-1 flex-col px-6 py-4 gap-4">
          <Skeleton className="h-12 w-full rounded-lg" />
          <div className="flex-1 space-y-3">
            {[1, 2, 3, 4, 5].map((i) => (
              <Skeleton key={i} className="h-20 w-3/4 rounded-xl" />
            ))}
            {[1, 2].map((i) => (
              <Skeleton key={i} className="ml-auto h-16 w-2/3 rounded-xl" />
            ))}
          </div>
          <Skeleton className="h-16 w-full rounded-xl" />
        </div>
      </div>
    </PageShell>
  )
}

function CalendarSkeleton() {
  return (
    <PageShell fullHeight>
      {/* Toolbar */}
      <div className="flex items-center justify-between border-b border-border/50 px-4 py-3">
        <div className="flex gap-2">
          <Skeleton className="h-9 w-9 rounded-lg" />
          <Skeleton className="h-9 w-9 rounded-lg" />
          <Skeleton className="h-9 w-32 rounded-lg" />
        </div>
        <div className="flex gap-2">
          <Skeleton className="h-9 w-20 rounded-lg" />
          <Skeleton className="h-9 w-20 rounded-lg" />
          <Skeleton className="h-9 w-20 rounded-lg" />
        </div>
      </div>
      {/* Day header row */}
      <div className="grid grid-cols-7 border-b border-border/50 px-4">
        {[1, 2, 3, 4, 5, 6, 7].map((i) => (
          <Skeleton key={i} className="mx-1 my-2 h-5 w-16 rounded" />
        ))}
      </div>
      {/* Time grid */}
      <div className="flex flex-1 min-h-0 px-4">
        {/* Time labels */}
        <div className="flex w-14 shrink-0 flex-col pt-2 gap-[26px]">
          {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <Skeleton key={i} className="h-3 w-10 rounded" />
          ))}
        </div>
        {/* Day columns */}
        <div className="grid flex-1 grid-cols-7 gap-1 pt-2">
          {[1, 2, 3, 4, 5, 6, 7].map((col) => (
            <div key={col} className="flex flex-col gap-2">
              {col % 3 !== 0 && <Skeleton className="h-16 w-full rounded-lg" style={{ marginTop: `${col * 24}px` }} />}
              {col % 2 === 0 && <Skeleton className="h-24 w-full rounded-lg" />}
            </div>
          ))}
        </div>
      </div>
    </PageShell>
  )
}

function HubSkeleton() {
  return (
    <PageShell>
      {/* Header */}
      <Skeleton className="h-8 w-52 mb-2" />
      <Skeleton className="h-4 w-72 mb-8" />
      {/* Prompt input area */}
      <Skeleton className="h-28 w-full rounded-xl mb-6" />
      {/* Style tags */}
      <div className="flex gap-2 mb-8">
        {[1, 2, 3, 4, 5, 6].map((i) => (
          <Skeleton key={i} className="h-7 w-20 rounded-full" />
        ))}
      </div>
      {/* Masonry-style image grid */}
      <Skeleton className="h-5 w-32 mb-3" />
      <div className="columns-2 sm:columns-3 lg:columns-4 gap-4">
        {(['h-48', 'h-64', 'h-56', 'h-72', 'h-48', 'h-80', 'h-56', 'h-60'] as const).map((h, i) => (
          <Skeleton key={i} className={`mb-4 w-full rounded-xl ${h}`} style={{ breakInside: 'avoid' }} />
        ))}
      </div>
    </PageShell>
  )
}

function ChartSkeleton() {
  return (
    <PageShell>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <Skeleton className="h-8 w-40 mb-1.5" />
          <Skeleton className="h-4 w-56" />
        </div>
        <div className="flex gap-2">
          <Skeleton className="h-9 w-24 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
        </div>
      </div>
      {/* Tab row */}
      <div className="flex gap-1 border-b border-border/50 mb-6">
        {[1, 2, 3, 4, 5, 6].map((i) => (
          <Skeleton key={i} className="h-9 w-24 rounded-t-md" />
        ))}
      </div>
      {/* KPI strip */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-8">
        {[1, 2, 3, 4].map((i) => (
          <Skeleton key={i} className="h-20 rounded-xl" />
        ))}
      </div>
      {/* Main chart area */}
      <Skeleton className="h-64 w-full rounded-xl mb-6" />
      {/* Secondary chart + breakdown */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Skeleton className="h-48 rounded-xl" />
        <Skeleton className="h-48 rounded-xl" />
      </div>
    </PageShell>
  )
}

function GenericSkeleton() {
  return (
    <PageShell>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <Skeleton className="h-8 w-44 mb-1.5" />
          <Skeleton className="h-4 w-60" />
        </div>
        <Skeleton className="h-9 w-32 rounded-lg" />
      </div>
      {/* Body blocks */}
      <div className="space-y-4">
        <Skeleton className="h-32 w-full rounded-xl" />
        <Skeleton className="h-48 w-full rounded-xl" />
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <Skeleton className="h-36 rounded-xl" />
          <Skeleton className="h-36 rounded-xl" />
        </div>
        <Skeleton className="h-24 w-full rounded-xl" />
      </div>
    </PageShell>
  )
}

export function PageSkeleton({ variant, fullHeight }: PageSkeletonProps) {
  switch (variant) {
    case 'dashboard':
      return <DashboardSkeleton />
    case 'list':
      return <ListSkeleton />
    case 'grid':
      return <GridSkeleton />
    case 'tabs':
      return <TabsSkeleton />
    case 'two-pane':
      return <TwoPaneSkeleton />
    case 'calendar':
      return <CalendarSkeleton />
    case 'hub':
      return <HubSkeleton />
    case 'chart':
      return <ChartSkeleton />
    case 'generic':
      return <GenericSkeleton />
  }
}
